"""Standalone Pickable Raspberry Pi operations and Hermes chat page."""

PI_PAGE_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pickable · Pi Control</title>
<style>
:root{color-scheme:dark;--bg:#0d1118;--card:#141b25;--card2:#101720;--line:#253243;--text:#edf3fa;--muted:#9caec2;--dim:#72869c;--cyan:#64d9d0;--green:#6fe0a2;--amber:#ffc86b;--red:#ff7d86;--blue:#90b8ff;--r:16px;font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--text);background:radial-gradient(900px 500px at 92% -8%,#152a3b 0,transparent 64%),radial-gradient(700px 500px at -15% 18%,#18282b 0,transparent 60%),var(--bg)}button,textarea{font:inherit}.shell{max-width:1240px;margin:auto;padding:28px clamp(18px,4vw,48px) 46px}.top{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:23px}.brand{display:flex;align-items:center;gap:13px}.mark{width:42px;height:42px;display:grid;place-items:center;border:1px solid #2e5960;border-radius:13px;color:var(--cyan);font-size:21px;background:#102427}.eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--cyan);font-weight:750}.brand h1{font-size:20px;margin:2px 0 0;letter-spacing:-.02em}.top-actions{display:flex;align-items:center;gap:12px}.link{color:var(--muted);text-decoration:none;font-size:13px}.link:hover{color:var(--cyan)}.pill{display:inline-flex;align-items:center;gap:8px;padding:7px 11px;border-radius:99px;border:1px solid var(--line);background:#101721;color:var(--muted);font-size:12px}.dot{width:7px;height:7px;background:var(--dim);border-radius:50%}.pill.ok .dot{background:var(--green);box-shadow:0 0 10px #6fe0a255}.pill.wait .dot{background:var(--amber)}.pill.bad .dot{background:var(--red)}.intro{padding:28px 0 20px;display:flex;align-items:end;justify-content:space-between;gap:20px}.intro h2{margin:0 0 5px;font-size:27px;letter-spacing:-.035em}.intro p{margin:0;color:var(--muted);max-width:670px}.updated{color:var(--dim);font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.grid{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.card{background:linear-gradient(160deg,#151e29,#111720);border:1px solid var(--line);border-radius:var(--r);padding:20px;min-width:0;box-shadow:0 12px 35px #0002}.card-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:17px}.card h3{font-size:14px;margin:0;letter-spacing:.01em}.kicker{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.12em}.refresh{border:1px solid var(--line);border-radius:9px;padding:7px 10px;background:#111923;color:var(--muted);font-size:12px;cursor:pointer}.refresh:hover{border-color:#42606f;color:var(--text)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{padding:14px;background:var(--card2);border:1px solid #202b39;border-radius:12px}.stat b{font:700 24px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:-.05em;display:block}.stat span{font-size:11px;color:var(--muted)}.progress-wrap{margin-top:18px}.progress-label{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-bottom:8px}.track{height:7px;background:#202a37;border-radius:99px;overflow:hidden}.fill{height:100%;width:0;background:linear-gradient(90deg,#58c9c7,#75e6ae);border-radius:99px;transition:width .35s ease}.now{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:18px;padding:13px 14px;background:#101720;border:1px solid #202b39;border-radius:12px}.now strong{display:block;font-size:13px}.now small{color:var(--muted)}.status-label{font-size:12px;color:var(--muted);text-align:right}.status-label.wait{color:var(--amber)}.status-label.bad{color:var(--red)}.status-label.ok{color:var(--green)}.pipeline-note{margin:13px 0 0;color:var(--dim);font-size:12px}.system-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.sys{padding:12px;background:var(--card2);border:1px solid #202b39;border-radius:11px}.sys span{display:block;color:var(--dim);font-size:10px;letter-spacing:.1em;text-transform:uppercase;margin-bottom:5px}.sys strong{font-size:13px}.state-ok{color:var(--green)}.state-warn{color:var(--amber)}.log{margin-top:14px;padding:12px;background:#0b1017;border:1px solid #202b39;border-radius:11px;color:#a8bbce;font:11px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap;overflow:auto;max-height:175px}.chat{grid-column:1/-1;display:flex;flex-direction:column;min-height:450px}.chat-title{display:flex;align-items:center;gap:9px}.chat-title .badge{font-size:10px;color:var(--cyan);border:1px solid #285054;padding:3px 7px;border-radius:99px}.chat-sub{font-size:12px;color:var(--dim);margin-top:4px}.messages{flex:1;min-height:260px;max-height:500px;overflow:auto;display:flex;flex-direction:column;gap:12px;padding:5px 1px 15px}.msg{max-width:min(790px,90%);border:1px solid var(--line);border-radius:13px;padding:11px 14px;background:#101720;white-space:pre-wrap;overflow-wrap:anywhere}.msg.user{align-self:flex-end;background:#15272b;border-color:#29484d}.msg.hermes{align-self:flex-start}.msg-head{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--dim);margin-bottom:5px}.msg.user .msg-head{color:var(--cyan)}.empty{display:grid;place-items:center;flex:1;min-height:220px;text-align:center;color:var(--muted);padding:25px}.empty strong{display:block;color:var(--text);margin-bottom:6px}.composer{display:flex;align-items:end;gap:10px;border-top:1px solid var(--line);padding-top:15px}.composer textarea{flex:1;min-height:48px;max-height:160px;resize:vertical;padding:12px 13px;color:var(--text);background:#0e141c;border:1px solid #2a394a;border-radius:11px;outline:none}.composer textarea:focus{border-color:#43888a}.composer button{height:46px;padding:0 18px;border:0;border-radius:11px;background:var(--cyan);color:#081416;font-weight:750;cursor:pointer}.composer button:disabled{opacity:.45;cursor:wait}.fine{font-size:11px;color:var(--dim);margin-top:10px}.error{color:var(--red)}@media(max-width:850px){.grid{grid-template-columns:1fr}.chat{grid-column:auto}.intro{align-items:start;flex-direction:column}.stats{gap:7px}.stat{padding:11px}.stat b{font-size:20px}}@media(max-width:520px){.shell{padding:19px 14px 30px}.brand h1{font-size:17px}.top{align-items:flex-start}.top-actions{align-items:flex-end;flex-direction:column;gap:7px}.intro h2{font-size:23px}.card{padding:15px}.sys strong{font-size:12px}.composer{align-items:stretch;flex-direction:column}.composer button{align-self:flex-end}.msg{max-width:96%}}
</style>
</head>
<body><main class="shell">
<header class="top"><div class="brand"><div class="mark">↗</div><div><div class="eyebrow">Pickable · Field Research</div><h1>Raspberry Pi Control</h1></div></div><div class="top-actions"><a class="link" href="http://127.0.0.1:8899/">← Shared Brain</a><span id="connection" class="pill"><i class="dot"></i><span>Connecting to Pi…</span></span></div></header>
<section class="intro"><div><h2>Scrape operations</h2><p>Pi’deki Reddit örneklemini ve Hermes zamanlayıcısını buradan izle; Hermes’e doğrudan mesaj gönder.</p></div><div id="updated" class="updated">Henüz bağlanmadı</div></section>
<div class="grid">
  <section class="card"><div class="card-head"><div><div class="kicker">Collection</div><h3 style="margin-top:4px">Topluluk örneklemi</h3></div><button id="refresh" class="refresh">↻ Yenile</button></div>
    <div class="stats"><div class="stat"><b id="posts">—</b><span>GÖNDERİ</span></div><div class="stat"><b id="comments">—</b><span>YORUM</span></div><div class="stat"><b id="communities">—</b><span>TAMAMLANAN TOPLULUK</span></div></div>
    <div class="progress-wrap"><div class="progress-label"><span>Topluluk ilerlemesi</span><strong id="progress-text">—</strong></div><div class="track"><div id="progress" class="fill"></div></div></div>
    <div class="now"><div><strong id="current">Durum alınıyor…</strong><small id="phase">—</small></div><div id="activity" class="status-label">—</div></div>
    <p class="pipeline-note">Sayaçlar her topluluk tamamlandığında checkpoint’ten güncellenir. 422 backoff, durma veya sessizlik ayrı durum olarak gösterilir.</p>
  </section>
  <section class="card"><div class="card-head"><div><div class="kicker">Pi services</div><h3 style="margin-top:4px">Hermes sağlık durumu</h3></div><span class="pill"><i class="dot"></i><span>SSH · arda-codex-pi</span></span></div>
    <div class="system-grid"><div class="sys"><span>Hermes gateway</span><strong id="gateway">—</strong></div><div class="sys"><span>Collector</span><strong id="collector">—</strong></div><div class="sys"><span>Auto-restart</span><strong id="supervisor">—</strong></div><div class="sys"><span>Hermes cron</span><strong id="cron">—</strong></div></div>
    <div id="log" class="log">Pi logları bekleniyor…</div>
  </section>
  <section class="card chat"><div class="card-head"><div><div class="chat-title"><h3>Raspberry Pi ile konuş</h3><span class="badge">HERMES AGENT</span></div><div class="chat-sub">Mesajlar SSH üzerinden Pi’deki Hermes’e gider; her tur mevcut scraper klasöründe başlar.</div></div><button id="clear-chat" class="refresh">Sohbeti temizle</button></div>
    <div id="messages" class="messages"></div>
    <form id="composer" class="composer"><textarea id="message" maxlength="6000" placeholder="Örn. 422 yanıtlarının nedenini loglardan incele; scrape’e dokunmadan açıkla…" rows="2"></textarea><button id="send" type="submit">Pi’ye gönder ↗</button></form>
    <div class="fine">Hermes’e yalnızca senin yazdığın talimatlar gönderilir. Reddit gönderileri ve yorumları güvenilmeyen veri sayılır; Hermes’e bu içeriklerdeki komutları takip etmemesi söylenir.</div>
  </section>
</div></main>
<script>
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let history=[];try{history=JSON.parse(localStorage.getItem('pi-hermes-chat')||'[]')}catch{};history=Array.isArray(history)?history.slice(-12):[];
function renderHistory(){const box=$('#messages');box.innerHTML=history.length?history.map(m=>`<div class="msg ${m.role==='user'?'user':'hermes'}"><div class="msg-head">${m.role==='user'?'You':'Hermes · Raspberry Pi'}</div>${esc(m.content)}</div>`).join(''):'<div class="empty"><div><strong>Pi Hermes hazır</strong>Scraper durumunu sorabilir veya çalışma için açık talimat verebilirsin.</div></div>';box.scrollTop=box.scrollHeight}
function setText(id,value){$(id).textContent=value??'—'}
function setState(id,value,ok){const e=$(id);e.textContent=value||'—';e.className=ok?'state-ok':'state-warn'}
function labelFor(s,d){if(s==='waiting')return `API ${d.lastBackoff?.code||'yanıtı'} backoff · ${Math.max(0,(d.lastBackoff?.seconds||0)-(d.logAgeSeconds||0))} sn`;if(s==='quiet')return `Sessiz · log ${d.logAgeSeconds||0} sn önce`;return ({running:'Çalışıyor · yeni çıktı var',stalled:'Takıldı · 5 dk+ log yok',recovering:'Yeniden başlıyor',stopped:'Çalışmıyor',completed:'Tamamlandı'})[s]||s||'Bilinmiyor'}
async function refreshStatus(){const pill=$('#connection');try{const r=await fetch('/api/pi/status',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||`HTTP ${r.status}`);pill.className='pill ok';pill.lastElementChild.textContent='Pi bağlı';const pct=d.totalCommunities?Math.min(100,100*d.completedCommunities/d.totalCommunities):0;setText('#posts',d.posts?.toLocaleString('en-US'));setText('#comments',d.comments?.toLocaleString('en-US'));setText('#communities',`${d.completedCommunities}/${d.totalCommunities}`);setText('#progress-text',`${d.completedCommunities} / ${d.totalCommunities}`);$('#progress').style.width=pct+'%';setText('#current',d.current?`r/${d.current.community}`:'Scraper işi');setText('#phase',d.current?.phase||'Yeni log kaydı yok');const a=$('#activity');a.textContent=labelFor(d.activity,d);a.className='status-label '+(d.activity==='running'||d.activity==='completed'?'ok':d.activity==='waiting'||d.activity==='quiet'||d.activity==='recovering'?'wait':'bad');setState('#gateway',d.hermesGateway,d.hermesGateway==='active');setState('#collector',d.collectorRunning?'Aktif':'Kapalı',d.collectorRunning);setState('#supervisor',d.supervisorRunning?'Aktif':'Kapalı',d.supervisorRunning);const cron=d.hermesCron||'';setState('#cron',cron.includes('heartbeat')||cron.includes('cron jobs will fire')?'Ticker güncel':cron.split('\n').find(x=>x.includes('stalled'))?.trim()||'Durum bilinmiyor',cron.includes('heartbeat')||cron.includes('cron jobs will fire'));$('#log').textContent=(d.recentLog||[]).join('\n')||'Henüz log kaydı yok.';setText('#updated','Son kontrol · '+new Date().toLocaleTimeString());}catch(e){pill.className='pill bad';pill.lastElementChild.textContent='Pi bağlantısı yok';setText('#updated','Bağlantı hatası');$('#activity').textContent=e.message;$('#activity').className='status-label bad'}}
$('#refresh').addEventListener('click',refreshStatus);renderHistory();refreshStatus();setInterval(refreshStatus,15000);
$('#clear-chat').addEventListener('click',()=>{history=[];localStorage.removeItem('pi-hermes-chat');renderHistory()});
$('#composer').addEventListener('submit',async e=>{e.preventDefault();const input=$('#message'),message=input.value.trim();if(!message)return;const previous=history.slice(-12),send=$('#send');history.push({role:'user',content:message});renderHistory();localStorage.setItem('pi-hermes-chat',JSON.stringify(history.slice(-12)));input.value='';send.disabled=true;send.textContent='Hermes düşünüyor…';const pending=document.createElement('div');pending.className='msg hermes';pending.textContent='Pi Hermes yanıt hazırlıyor…';$('#messages').appendChild(pending);$('#messages').scrollTop=$('#messages').scrollHeight;try{const r=await fetch('/api/pi/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,history:previous})});const d=await r.json();if(!r.ok)throw Error(d.error||`HTTP ${r.status}`);history.push({role:'assistant',content:d.answer});history=history.slice(-12);localStorage.setItem('pi-hermes-chat',JSON.stringify(history));renderHistory();refreshStatus()}catch(err){pending.className='msg hermes error';pending.textContent='Pi Hermes hatası: '+err.message}finally{send.disabled=false;send.textContent='Pi’ye gönder ↗';input.focus()}});
</script></body></html>"""
